changeSet.sql:
DO $grants$
DECLARE
    t text;
    readable text[] := ARRAY[
        'syllabus_extractions', 'topics', 'topic_prerequisites', 'item_annotations', 'attempt_answers',
        'assessment_attempts', 'enrollments', 'human_gradings', 'video_relevance_judgments',
        'video_candidates', 'user_profiles', 'badges', 'path_steps', 'diagnostics', 'survey_responses',
        'llm_call_logs', 'ai_jobs', 'resources',
        'v_path_step_metrics', 'v_llm_cost_summary', 'v_item_validity'];
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'smartmentor_metrics') THEN
        GRANT USAGE ON SCHEMA public TO smartmentor_metrics;
        FOREACH t IN ARRAY readable LOOP
            EXECUTE format('GRANT SELECT ON %I TO smartmentor_metrics', t);
        END LOOP;
    ELSE
        RAISE NOTICE 'Role smartmentor_metrics does not exist: grants skipped';
    END IF;
END
$grants$;

rollback.sql:
DO $revoke$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'smartmentor_metrics') THEN
        REVOKE ALL ON ALL TABLES IN SCHEMA public FROM smartmentor_metrics;
        REVOKE USAGE ON SCHEMA public FROM smartmentor_metrics;
    END IF;
END
$revoke$;
